import pytest

from bedrock_protocol import v2225

# generated by gophertunnel b8bd735:
# &packet.AgentAction{Identifier: "req-1", Action: packet.AgentActionTypeTransferItemTo,
# Response: []byte("{\"ok\":true}")}
TRANSFER = bytes.fromhex("057265712d31110000000b7b226f6b223a747275657d")

# generated by gophertunnel b8bd735:
# &packet.AgentAction{Action: packet.AgentActionTypeAttack}
ATTACK = bytes.fromhex("000100000000")

GOLDENS = [
    pytest.param(
        v2225.AgentActionEventPacket(
            request_id="req-1", action=v2225.AgentActionType.TRANSFER_ITEM_TO, response='{"ok":true}'
        ),
        TRANSFER,
        id="transfer-item-to",
    ),
    pytest.param(v2225.AgentActionEventPacket(action=v2225.AgentActionType.ATTACK), ATTACK, id="attack"),
]


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_agent_action_event_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_agent_action_event_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
